function vf(label, form, example_ru, example_it) {
  return { label, form, example_ru, example_it };
}

function vb(word, meaning_it, aspect, note_it, forms) {
  return { word, meaning_it, aspect, note_it, forms: forms.map((f) => vf(...f)) };
}

// Coppia aspettuale: un verbo imperfettivo e il suo corrispondente perfettivo,
// ciascuno con le proprie forme coniugate, più un mini-esercizio situazionale
// che allena a riconoscere quale aspetto usare in un contesto reale.
function vbPair(impfWord, impfForms, perfWord, perfForms, meaning_it, note_it, situational) {
  return {
    meaning_it,
    note_it,
    imperfective: { word: impfWord, forms: impfForms },
    perfective: { word: perfWord, forms: perfForms },
    situational,
  };
}

function sq(prompt_it, correctRu, correctAspect, wrongRu, wrongAspect) {
  return {
    prompt_it,
    options: [
      { ru: correctRu, aspect: correctAspect },
      { ru: wrongRu, aspect: wrongAspect },
    ],
    correct: 0,
  };
}

// ---------- Aggettivi: concordanza totale (genere, numero, caso) ----------

function af(label, form, noun, example_ru, example_it) {
  return { label, form, noun, example_ru, example_it };
}

function adj(word, meaning_it, note_it, genderForms, caseForms, transform) {
  return { word, meaning_it, note_it, genderForms, caseForms, transform };
}

